class Point {
    // FIELD: holds state
    int x;

    // CONSTRUCTOR: runs once, when an object is created with 'new'
    Point(int x) {
        this.x = x;
    }

    // METHOD: defines behavior objects of this class can perform
    int doubled() {
        return x * 2;
    }
}

public class Main {
    public static void main(String[] args) {
        Point p = new Point(5);
        System.out.println(p.doubled());
    }
}

