    public static void main(String[] args) {

        // Two separate objects, built from the SAME Car class
        Car car1 = new Car("Honda", "Civic");
        Car car2 = new Car("Tesla", "Model 3");

        car1.drive(250);
        car2.drive(80);

        car1.refuel();

        System.out.println("car1 fuel: " + car1.getFuelLevel());
        System.out.println("car2 fuel: " + car2.getFuelLevel());
    }
}

// The Car class: the blueprint every Car object below is built from
class Car {
    // Fields: the STATE every Car object carries around
    private String brand;
    private String model;
    private int fuelLevel;

    // Constructor: runs once when 'new Car(...)' is called
    public Car(String brand, String model) {
        this.brand = brand;
        this.model = model;
        this.fuelLevel = 100; // every new car starts with a full tank
    }

    // Method: BEHAVIOR - driving consumes fuel
    public void drive(int distanceKm) {
        int fuelUsed = distanceKm / 10; // simple rule: 10km costs 1% fuel
        fuelLevel = Math.max(0, fuelLevel - fuelUsed); // never let fuel go negative
        System.out.println(brand + " " + model + " drove " + distanceKm
            + "km. Fuel left: " + fuelLevel + "%");
    }

    // Method: BEHAVIOR - refueling resets the tank
    public void refuel() {
        fuelLevel = 100;
        System.out.println(brand + " " + model + " refueled to 100%");
    }

    // Method: exposes the private fuelLevel field in a controlled, read-only way
    public int getFuelLevel() {
        return fuelLevel;
    }
}

