#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

// The Car class: the blueprint every Car object below is built from
class Car {
private:
    // Fields: the STATE every Car object carries around
    string brand;
    string model;
    int fuelLevel;

public:
    // Constructor: runs once when a new Car is created
    Car(string brand, string model) {
        this->brand = brand;
        this->model = model;
        this->fuelLevel = 100; // every new car starts with a full tank
    }

    // Method: BEHAVIOR - driving consumes fuel
    void drive(int distanceKm) {
        int fuelUsed = distanceKm / 10; // simple rule: 10km costs 1% fuel
        fuelLevel = max(0, fuelLevel - fuelUsed); // never let fuel go negative
        cout << brand << " " << model << " drove " << distanceKm
             << "km. Fuel left: " << fuelLevel << "%" << endl;
    }

    // Method: BEHAVIOR - refueling resets the tank
    void refuel() {
        fuelLevel = 100;
        cout << brand << " " << model << " refueled to 100%" << endl;
    }

    // Method: exposes the private fuelLevel field in a controlled, read-only way
    int getFuelLevel() {
        return fuelLevel;
    }
};

int main() {
    // Two separate objects, built from the SAME Car class
    Car car1("Honda", "Civic");
    Car car2("Tesla", "Model 3");

    car1.drive(250);
    car2.drive(80);

    car1.refuel();

    cout << "car1 fuel: " << car1.getFuelLevel() << endl;
    cout << "car2 fuel: " << car2.getFuelLevel() << endl;

    return 0;
}
